/// Checks if the value `x` is in the slice `a`.
fn in_array(a: &[i32], x: i32) -> bool {
    a.iter().any(|&item| item == x)
}

/// Wrapper function to check if the value `x` is in the slice `a`.
fn is_in_array(a: &[i32], x: i32) -> bool {
    in_array(a, x)
}

/// Checks if the value `x` is in the vector `v`.
fn contains(v: &Vec<i32>, x: i32) -> bool {
    v.iter().any(|&item| item == x)
}

/// Removes elements from slice `a` that are present in slice `b`.
fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32> {
    let mut result = Vec::new();
    let mut seen = std::collections::HashSet::new();

    for &item in a {
        if !in_array(b, item) && !seen.contains(&item) {
            result.push(item);
            seen.insert(item);
        }
    }

    result
}

fn main() {
    // Example usage
    let a = [1, 2, 3, 4, 5, 2, 3];
    let b = [3, 4, 5];
    let result = remove_elements(&a, &b);
    println!("{:?}", result); // Output: [1, 2]
}